CREATE TABLE chat_rooms (id char(36) PRIMARY KEY,kind varchar(12) NOT NULL,title varchar(100) NOT NULL DEFAULT '',owner_id char(36) NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,direct_key varchar(73) UNIQUE,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE chat_members (room_id char(36) REFERENCES chat_rooms(id) ON DELETE CASCADE,student_id char(36) REFERENCES profiles(id) ON DELETE CASCADE,last_read_at timestamptz,joined_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(room_id,student_id));
CREATE TABLE chat_messages (id char(36) PRIMARY KEY,room_id char(36) NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE,sender_id char(36) NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,client_id char(36) NOT NULL,body varchar(2000) NOT NULL,hidden smallint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(sender_id,client_id));
CREATE INDEX idx_chat_messages_room ON chat_messages(room_id,created_at,id);
CREATE TABLE chat_blocks (student_id char(36) REFERENCES profiles(id) ON DELETE CASCADE,peer_id char(36) REFERENCES profiles(id) ON DELETE CASCADE,PRIMARY KEY(student_id,peer_id));
CREATE TABLE chat_reports (id char(36) PRIMARY KEY,message_id char(36) NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,reporter_id char(36) NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,reason varchar(500) NOT NULL,status varchar(12) NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(message_id,reporter_id));
ALTER TABLE chat_rooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE chat_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE chat_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE chat_blocks ENABLE ROW LEVEL SECURITY;
ALTER TABLE chat_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE chat_rooms,chat_members,chat_messages,chat_blocks,chat_reports FROM PUBLIC,anon,authenticated;
